#!/bin/bash
#SBATCH --partition=h200debugq
#SBATCH --nodes=1
#SBATCH --ntasks=1
#SBATCH --gres=gpu:h200:1
#SBATCH --cpus-per-task=8
#SBATCH --mem=64G
#SBATCH --time=0:30:00
#SBATCH --job-name=toy-gpu
#SBATCH --output=/scratch/user/studies/toy/logs/gpu-%j.out
#SBATCH --no-requeue

# Generated by SimLaunch 0.1.0: study toy, spec gpu, site kepler.
# 1 runs, sequential. Plain bash; nothing else is needed to run it.

set -u

STUDY=toy
SPEC=gpu
DESCRIPTION=''        # for SimWatch, as a TOML string; empty: none
SITE=kepler
CODE=/home/user/studies/toy
PROJECT=/home/user/studies/toy/src/Toy
TOOLS=/home/user/studies/toy/tools
DEPOT=/home/user/studies/toy/depot-h200      # the study's compiled caches, for this architecture
SCRATCH=/scratch/user/studies/toy
JULIA="$HOME"/.juliaup/bin/julia
USE_SLURM=1
TIME_LIMIT=1800        # seconds; empty: none
NODES=1
GPUS=1
LABELS=(n3)
THREADS=(8)
RANKS=(0)
JOBDIRS=()
SKIP=()
PIDS=()
TERMINATED=
CHECKPOINTS=0        # 1: the runs continue from the checkpoints of earlier jobs
MUTABLE=0            # 1: one shared directory for all jobs of a run
CONTINUE_CODE=        # the driver's exit code when it stops at its walltime
SUCCESSOR=0

# --- SimLaunch helpers: directories, restarts and SimWatch status files ------

run_dir() {   # RUN-INDEX: the run's directory, which holds one directory per job
    echo "$SCRATCH/$SPEC-${LABELS[$1]}"
}

# node_list N [SUFFIX]: the job's first N nodes, with commas between them and SUFFIX after each: where a
# run under an mpiexec starts its ranks.
node_list() {
    scontrol show hostnames "$SLURM_JOB_NODELIST" |
        awk -v n="$1" -v s="${2:-}" 'NR <= n { printf "%s%s%s", (NR > 1 ? "," : ""), $0, s }'
}

sw_now() {
    date -u +%Y-%m-%dT%H:%M:%SZ
}

# usage_kb RUN-INDEX: what the run's ended jobs hold, in KiB, as far as it was measured.
usage_kb() {
    awk '/^kb = [0-9]+$/ { s += $3 } END { print s + 0 }' "$(run_dir "$1")/diskusage.toml" 2>/dev/null || echo 0
}

# sw_write RUN-INDEX STATUS MESSAGE [NEXT-JOB]: rewrite the run's simwatch.toml.
sw_write() {
    local i=$1 status=$2 message=$3 next=${4:-} dir f tmp prev prog
    dir=$(run_dir "$i")
    f=$dir/simwatch.toml
    tmp=$f.tmp.$$.$RANDOM
    {
        echo "name = \"$SPEC/${LABELS[$i]}\""         # the study is the group
        echo "status = \"$status\""
        echo "code = \"SimLaunch\""
        echo "group = \"$STUDY\""
        if [ -n "$DESCRIPTION" ]; then echo "description = $DESCRIPTION"; fi
        echo "updated = $(sw_now)"
        echo "started = $SW_STARTED"
        echo "update_interval = 60"
        echo "host = \"$(hostname -s)\""
        echo "message = \"$message\""
        echo
        echo "[progress]"
        if [ "$status" = finished ]; then echo "fraction = 1.0"; fi
        echo "walltime = $(( $(date +%s) - SW_T0 ))"
        if [ -n "$TIME_LIMIT" ]; then echo "walltime_limit = $TIME_LIMIT"; fi
        echo
        echo "[resources]"
        echo "nodes = $NODES"
        if [ "${RANKS[$i]}" -gt 0 ]; then echo "tasks = ${RANKS[$i]}"; fi
        echo "threads = ${THREADS[$i]}"
        if [ "$GPUS" -gt 0 ]; then echo "gpus = $GPUS"; fi
        if [ -f "$dir/diskusage.toml" ]; then
            echo
            echo "[diskusage]                  # of the jobs that have ended"
            echo "kb = $(usage_kb "$i")"
        fi
        if [ -n "${SLURM_JOB_ID:-}" ]; then
            echo
            echo "[slurm]"
            echo "job_id = \"$SLURM_JOB_ID\""
            echo "job_name = \"${SLURM_JOB_NAME:-}\""
            echo "partition = \"${SLURM_JOB_PARTITION:-}\""
            sw_cluster
            prev=$(grep -vxF "$JOBID" "$dir/.simlaunch-jobs" 2>/dev/null | sed 's/.*/"&"/' | paste -sd, -)
            if [ -n "$prev" ]; then echo "previous_job_ids = [$prev]"; fi
            if [ -n "$next" ]; then echo "next_job_id = \"$next\""; fi
        fi
    } > "$tmp" || return 0
    prog=${JOBDIRS[$i]:-}/.simwatch/simwatch.toml
    if [ -n "${JOBDIRS[$i]:-}" ] && [ -f "$prog" ] && [ "$(wc -c < "$prog")" -le 131072 ]; then
        if sw_merge "$tmp" "$prog" "$status" "$(basename "${JOBDIRS[$i]}")" > "$tmp.m"; then
            mv -f "$tmp.m" "$tmp"
        else
            rm -f "$tmp.m"
        fi
    fi
    mv -f "$tmp" "$f"
    return 0
}

# sw_merge OURS PROGRAM STATUS JOBDIR-NAME: our SimWatch file with what the
# program reports in its own, $SIMLAUNCH_SIMWATCH_DIR/simwatch.toml: its
# progress, summary and tables. Our keys win, but for the program's message
# while it runs; its [slurm] and [diskusage] are left out, and its images are
# found in its directory. Reads TOML line by line, as SimWatch's writers and
# TOML.print write it: one key a line, a header on a line of its own.
sw_merge() {
    awk -v status="$3" -v jd="$4" '
        function keyof(s) {
            if (s !~ /^[ \t]*("[^"]*"|[A-Za-z0-9_.-]+)[ \t]*=/) return ""
            sub(/^[ \t]*/, "", s); sub(/[ \t]*=.*$/, "", s); return s
        }
        FNR == 1 { f++; k = 0; nsec[f] = 0 }
        /^[ \t]*$/ { next }
        /^[ \t]*\[/ {
            k = ++nsec[f]; head[f, k] = $0
            name = $0; sub(/^[ \t]*/, "", name); sub(/\][^]]*$/, "]", name)
            sname[f, k] = name
            if (!((f, name) in idx)) idx[f, name] = k
            next
        }
        {
            key = keyof($0)
            if (key == "" && $0 !~ /^[ \t]*#/ && ne[f, k] > 0) { entry[f, k, ne[f, k]] = entry[f, k, ne[f, k]] "\n" $0; next }
            j = ++ne[f, k]; entry[f, k, j] = $0; ekey[f, k, j] = key
            if (key != "") pos[f, k, key] = j
        }
        # our entries of section a, then the keys of the program section b that we lack
        function merged(a, b,   j, key) {
            for (j = 1; j <= ne[1, a]; j++) {
                key = ekey[1, a, j]
                if (key == "message" && status == "running" && b >= 0 && ((2, b, key) in pos)) print entry[2, b, pos[2, b, key]]
                else print entry[1, a, j]
            }
            if (b < 0) return
            for (j = 1; j <= ne[2, b]; j++) {
                key = ekey[2, b, j]
                if (key != "" && !((1, a, key) in pos)) print entry[2, b, j]
            }
        }
        END {
            merged(0, 0)
            for (k = 1; k <= nsec[1]; k++) {
                print ""; print head[1, k]
                merged(k, ((2, sname[1, k]) in idx) ? idx[2, sname[1, k]] : -1)
            }
            for (k = 1; k <= nsec[2]; k++) {
                name = sname[2, k]
                if (((1, name) in idx) || name ~ /^\[(slurm|diskusage)[].]/) continue
                print ""; print head[2, k]
                for (j = 1; j <= ne[2, k]; j++) {
                    line = entry[2, k, j]
                    if (name == "[[images]]" && ekey[2, k, j] == "file") sub(/=[ \t]*"/, "= \"" jd "/.simwatch/", line)
                    print line
                }
            }
        }' "$1" "$2"
}

# sw_status RUN-INDEX: the status in the run's simwatch.toml, or nothing.
sw_status() {
    sed -n 's/^status = "\(.*\)"$/\1/p' "$(run_dir "$1")/simwatch.toml" 2>/dev/null | head -n 1
}

# at_limit: true once the job is within a minute of its time limit.
at_limit() {
    [ -n "$TIME_LIMIT" ] && [ $(( $(date +%s) - SW_T0 )) -ge $(( TIME_LIMIT - 60 )) ]
}

# sw_cancel RUN-INDEX MESSAGE: mark a run that has not ended as cancelled, a
# final state for SimWatch; the rest of its file stays. Prints the run's
# label if it was marked. For `simlaunch cancel`, before and after the jobs
# are cancelled.
sw_cancel() {
    local f tmp msg
    f=$(run_dir "$1")/simwatch.toml
    case $(sw_status "$1") in
        queued|starting|running|stopped|cancelled) ;;
        *) return 0 ;;
    esac
    msg=$(printf '%s' "$2" | tr -d '"\\|&\n')
    tmp=$f.tmp.$$.$RANDOM
    sed -e 's/^status = .*/status = "cancelled"/' -e "s/^updated = .*/updated = $(sw_now)/" \
        -e "s|^message = .*|message = \"$msg\"|" "$f" > "$tmp" && mv -f "$tmp" "$f" && echo "${LABELS[$1]}"
}

# sw_cluster: the line that names this Slurm, for a site where one file system
# is shared by several (Trillium's CPU and GPU clusters): SimWatch compares a
# job only with the queue of its own cluster. A job knows the name; at submit
# time Slurm is asked, once.
sw_cluster() {
    if [ -z "${SW_CLUSTER+x}" ]; then
        SW_CLUSTER=${SLURM_CLUSTER_NAME:-}
        if [ -z "$SW_CLUSTER" ]; then
            SW_CLUSTER=$(scontrol show config 2>/dev/null | awk '$1 == "ClusterName" { print $3; exit }') || true
        fi
    fi
    if [ -n "$SW_CLUSTER" ]; then echo "cluster = \"$SW_CLUSTER\""; fi
    return 0
}

# sw_queued RUN-INDEX [LATER-JOBS]: a submitted job, before it starts. Does
# nothing if the job has started already.
sw_queued() {
    local i=$1 later=${2:-} dir f tmp id= prev
    dir=$(run_dir "$i")
    f=$dir/simwatch.toml
    tmp=$f.tmp.$$.$RANDOM
    mkdir -p "$dir" || return
    if [ -f "$dir/.simlaunch-job" ]; then read -r id _ < "$dir/.simlaunch-job"; fi
    if [ "$id" = "$JOBID" ]; then return 0; fi
    {
        echo "name = \"$SPEC/${LABELS[$i]}\""         # the study is the group
        echo "status = \"queued\""
        echo "code = \"SimLaunch\""
        echo "group = \"$STUDY\""
        if [ -n "$DESCRIPTION" ]; then echo "description = $DESCRIPTION"; fi
        echo "updated = $(sw_now)"
        echo "message = \"queued as job $JOBID${later:+, then $later}\""
        if [ "$USE_SLURM" = 1 ]; then
            echo
            echo "[slurm]"
            echo "job_id = \"$JOBID\""
            sw_cluster
            prev=$(sed 's/.*/"&"/' "$dir/.simlaunch-jobs" 2>/dev/null | paste -sd, -)
            if [ -n "$prev" ]; then echo "previous_job_ids = [$prev]"; fi
        fi
    } > "$tmp" && mv -f "$tmp" "$f"
}

# job_dirs RUN-INDEX: the run's job directories, oldest first.
job_dirs() {
    find "$(run_dir "$1")" -mindepth 1 -maxdepth 1 -type d -name '[0-9][0-9][0-9]-*' 2>/dev/null | sort
}

# new_job_dir RUN-INDEX: this job's own directory in the run, numbered in order.
new_job_dir() {
    local dir n
    dir=$(run_dir "$1")
    if [ "$MUTABLE" = 1 ]; then echo "$dir/mutable"; return; fi
    # the run's directory may not exist yet: a job can start before it is marked queued
    n=$(job_dirs "$1" | wc -l)
    printf '%s/%03d-%s\n' "$dir" $((n + 1)) "$JOBID"
}

# run_finished RUN-INDEX: true if an earlier job has finished the run.
run_finished() {
    local id= state= rc=
    if [ -f "$(run_dir "$1")/.simlaunch-job" ]; then read -r id state rc _ < "$(run_dir "$1")/.simlaunch-job"; fi
    [ "$state" = done ] && [ "$rc" = 0 ]
}

# du_kb DIR: its size in KiB, or "unknown" if it cannot be measured within 60 s.
du_kb() {
    local limit= out
    if command -v timeout > /dev/null 2>&1; then limit="timeout 60"; fi
    out=$($limit du -sk "$1" 2>/dev/null | cut -f1)
    echo "${out:-\"unknown\"}"
}

# record_usage RUN-INDEX JOBDIR: add the size of a job's directory, and of its
# checkpoints, to the run's diskusage.toml. Once per job.
record_usage() {
    local f name ck=0
    f=$(run_dir "$1")/diskusage.toml
    name=$(basename "$2")
    [ -d "$2" ] || return 0
    if grep -qxF "dir = \"$name\"" "$f" 2>/dev/null; then return 0; fi
    if [ -d "$2/ck" ]; then ck=$(du_kb "$2/ck"); fi
    printf '[[job]]\ndir = "%s"\nkb = %s\ncheckpoints_kb = %s\n\n' "$name" "$(du_kb "$2")" "$ck" >> "$f"
}

# seal_earlier RUN-INDEX: what the run's earlier jobs wrote is read-only and
# measured, also where a job was killed before it could do that itself.
seal_earlier() {
    local d
    while IFS= read -r d; do
        if [ "$d" = "${JOBDIRS[$1]}" ]; then continue; fi
        chmod -R a-w "$d" 2>/dev/null
        record_usage "$1" "$d"
    done < <(job_dirs "$1")
}

# restart_source RUN-INDEX: the ck/ of the newest earlier job that holds a
# complete checkpoint, or nothing. A checkpoint under a temporary name is one
# that was still being written.
restart_source() {
    local d found= pat complete=()
    for pat in ${TEMPORARY[@]+"${TEMPORARY[@]}"}; do complete+=(! -name "$pat"); done
    while IFS= read -r d; do
        if [ "$d" = "${JOBDIRS[$1]}" ] || [ ! -d "$d/ck" ]; then continue; fi
        if [ -n "$(find "$d/ck" -mindepth 1 -maxdepth 1 ${complete[@]+"${complete[@]}"} 2>/dev/null | head -n 1)" ]; then
            found=$d/ck
        fi
    done < <(job_dirs "$1")
    echo "$found"
}

# cpu_model: the CPU of this node, as lscpu or macOS names it.
cpu_model() {
    local m
    m=$(lscpu 2>/dev/null | sed -n 's/^Model name:[[:space:]]*//p' | head -n 1)
    if [ -z "$m" ]; then m=$(sysctl -n machdep.cpu.brand_string 2>/dev/null); fi
    echo "${m:-unknown}" | tr -d '"\\'
}

# job_record RUN-INDEX: where and when this job runs the run; kept in the
# job's directory as simlaunch-job.toml, with the results.
job_record() {
    local g
    echo "run = \"$SPEC-${LABELS[$1]}\""
    echo "job_id = \"$JOBID\""
    echo "started = $(sw_now)"
    echo "host = \"$(hostname -s)\""
    echo "cpu = \"$(cpu_model)\"        # of this host; a job's other nodes can differ"
    if [ -n "${SLURM_JOB_NODELIST:-}" ]; then echo "nodes = \"$SLURM_JOB_NODELIST\""; fi
    if [ -n "${SLURM_JOB_PARTITION:-}" ]; then echo "partition = \"$SLURM_JOB_PARTITION\""; fi
    if [ "$GPUS" -gt 0 ]; then
        g=$(nvidia-smi --query-gpu=name --format=csv,noheader 2>/dev/null | sort -u | paste -sd, - | tr -d '"\\')
        if [ -n "$g" ]; then echo "gpu = \"$g\""; fi
    fi
}

# run_one RUN-INDEX: run it in its job directory, keep its SimWatch file
# current, and make the directory read-only when it has ended. Call in a
# subshell; exits with the run's exit code.
run_one() {
    local i=$1 dir jobdir=${JOBDIRS[$1]} pid heartbeat rc src next= told=
    dir=$(run_dir "$i")
    cd "$jobdir" || exit 1
    grep -qxF "$JOBID" "$dir/.simlaunch-jobs" 2>/dev/null || echo "$JOBID" >> "$dir/.simlaunch-jobs"
    echo "$JOBID running" > "$dir/.simlaunch-job"
    job_record "$i" > "$jobdir/simlaunch-job.toml"
    RESTART_ARGS=()
    if [ "$CHECKPOINTS" = 1 ]; then
        mkdir -p "$jobdir/ck"
        RESTART_ARGS+=("$RESTART_TO=$jobdir/ck")
        if [ "$MUTABLE" = 0 ]; then
            src=$(restart_source "$i")
            if [ -n "$src" ]; then
                RESTART_ARGS+=("$RESTART_FROM=$src")
                echo "run ${LABELS[$i]}: continues from $src"
            else
                echo "run ${LABELS[$i]}: no earlier checkpoint, starts at the beginning"
            fi
        fi
        if [ -n "$RESTART_WALLTIME" ] && [ -n "$TIME_LIMIT" ]; then
            RESTART_ARGS+=("$RESTART_WALLTIME=$(( TIME_LIMIT - MARGIN - ($(date +%s) - SW_T0) ))")
        fi
    fi
    # where the program may write its own SimWatch file, merged into the run's; hidden, so that SimWatch
    # does not show it beside the run
    export SIMLAUNCH_SIMWATCH_DIR=$jobdir/.simwatch
    mkdir -p "$SIMLAUNCH_SIMWATCH_DIR"
    sw_write "$i" running "running in $(basename "$jobdir")"
    ( while sleep 60; do sw_write "$i" running "running in $(basename "$jobdir")"; done ) &
    heartbeat=$!
    "run_$i" > "$jobdir/output.log" 2>&1 &
    pid=$!
    trap 'told=1; kill -TERM "$pid" 2>/dev/null' TERM INT
    wait "$pid"; rc=$?
    while kill -0 "$pid" 2>/dev/null; do wait "$pid"; rc=$?; done
    kill "$heartbeat" 2>/dev/null
    wait "$heartbeat" 2>/dev/null
    if [ "$MUTABLE" = 0 ]; then
        chmod -R a-w "$jobdir"
        record_usage "$i" "$jobdir"
    fi
    if [ "$rc" -eq 0 ]; then
        echo "$JOBID done 0" > "$dir/.simlaunch-job"
        sw_write "$i" finished "finished in $(basename "$jobdir")"
    elif [ -n "$told" ] && [ "$(sw_status "$i")" = cancelled ]; then
        # `simlaunch cancel` marked the run before it cancelled the job: the mark stays
        echo "$JOBID cancelled $rc" > "$dir/.simlaunch-job"
    elif [ "$CHECKPOINTS" = 1 ] && [ -n "$CONTINUE_CODE" ] && [ "$rc" -eq "$CONTINUE_CODE" ]; then
        # the driver stopped at its walltime: not a failure
        echo "$JOBID stopped $rc" > "$dir/.simlaunch-job"
        sw_write "$i" stopped "stopped at its walltime in $(basename "$jobdir"); the next job continues it"
        rc=0
    elif [ "$CHECKPOINTS" = 1 ] && [ -n "$told" ]; then
        next=$(cat "$SCRATCH/logs/$SPEC-$JOBID.next" 2>/dev/null)
        echo "$JOBID stopped $rc" > "$dir/.simlaunch-job"
        sw_write "$i" stopped "stopped by a signal in $(basename "$jobdir"); ${next:+job $next continues it}${next:-a later job continues it}" "$next"
    elif [ -n "$told" ] && at_limit; then
        echo "$JOBID done $rc" > "$dir/.simlaunch-job"
        sw_write "$i" failed "killed at the time limit in $(basename "$jobdir") on $(hostname -s)"
    elif [ -n "$told" ]; then
        # ended from outside before the time limit: scancel, or a pre-emption without checkpoints
        echo "$JOBID cancelled $rc" > "$dir/.simlaunch-job"
        sw_write "$i" cancelled "the job was cancelled in $(basename "$jobdir") on $(hostname -s)"
    else
        echo "$JOBID done $rc" > "$dir/.simlaunch-job"
        sw_write "$i" failed "exit code $rc in $(basename "$jobdir") on $(hostname -s)"
    fi
    exit "$rc"
}

# wait_runs: wait for the runs in PIDS; fails if one of them failed.
wait_runs() {
    local pid rc bad=0
    for pid in "${PIDS[@]}"; do
        wait "$pid"; rc=$?
        while kill -0 "$pid" 2>/dev/null; do wait "$pid"; rc=$?; done
        if [ "$rc" -ne 0 ]; then bad=1; fi
    done
    return $bad
}

# submit_successor: a job stopped on a pre-emptible queue continues in a new
# job, which cannot start before this one has ended. Not at the time limit,
# where a chain or `simlaunch resubmit` continues, and not while the file
# $SCRATCH/STOP exists.
submit_successor() {
    local pending next i
    if [ "$SUCCESSOR" != 1 ]; then return 0; fi
    for i in "${!LABELS[@]}"; do
        if [ "$(sw_status "$i")" = cancelled ]; then echo "job $JOBID: run ${LABELS[$i]} is cancelled, no successor"; return 0; fi
    done
    if [ -e "$SCRATCH/STOP" ]; then echo "job $JOBID: $SCRATCH/STOP exists, no successor"; return 0; fi
    if at_limit; then return 0; fi
    pending=$(squeue -h -u "$(id -un)" -n "${SLURM_JOB_NAME:-}" -t PENDING -o %i 2>/dev/null | head -n 1)
    if [ -n "$pending" ]; then echo "job $JOBID: job $pending is queued already and continues"; return 0; fi
    next=$(sbatch --parsable $SBATCH_EXPORT --dependency=afterany:"$JOBID" "$SCRIPT" 2>&1)
    next=${next%%;*}
    case $next in
        ''|*[!0-9]*) echo "job $JOBID: could not submit a successor: $next" ;;
        *) echo "$next" > "$SCRATCH/logs/$SPEC-$JOBID.next"
           echo "job $JOBID: stopped before its time limit; job $next continues it" ;;
    esac
}

# The job was told to stop (time limit, pre-emption, scancel): pass it on to
# the runs.
on_term() {
    TERMINATED=1
    echo "job $JOBID: told to stop at $(date)"
    submit_successor
    kill -TERM ${PIDS[@]+"${PIDS[@]}"} 2>/dev/null
}

# When the job ends, however it ends: mark the runs that did not end by
# themselves, make every job directory read-only, and echo the runs' output
# into the job's log.
finish() {
    local rc=$? i dir id state next
    for i in "${!LABELS[@]}"; do
        if [ "${SKIP[$i]:-0}" = 1 ]; then continue; fi
        dir=$(run_dir "$i")
        id= state=
        if [ -f "$dir/.simlaunch-job" ]; then read -r id state _ < "$dir/.simlaunch-job"; fi
        if [ "$id" != "$JOBID" ] || [ "$state" = running ]; then
            if [ "$MUTABLE" = 0 ] && [ -d "${JOBDIRS[$i]:-}" ]; then
                chmod -R a-w "${JOBDIRS[$i]}"
                record_usage "$i" "${JOBDIRS[$i]}"
            fi
            if [ "$(sw_status "$i")" = cancelled ]; then
                echo "$JOBID cancelled $rc" > "$dir/.simlaunch-job"
            elif [ -n "$TERMINATED" ] && [ "$CHECKPOINTS" = 0 ] && ! at_limit; then
                sw_write "$i" cancelled "job $JOBID was cancelled before this run finished"
                echo "$JOBID cancelled $rc" > "$dir/.simlaunch-job"
            elif [ -n "$TERMINATED" ] && [ "$CHECKPOINTS" = 1 ] && [ "$id" != "$JOBID" ]; then
                # told to stop before this run started: a later job of the chain runs it
                next=$(cat "$SCRATCH/logs/$SPEC-$JOBID.next" 2>/dev/null)
                sw_write "$i" stopped "job $JOBID stopped before this run started; ${next:+job $next runs it}${next:-a later job runs it}" "$next"
                echo "$JOBID stopped $rc" > "$dir/.simlaunch-job"
            else
                sw_write "$i" failed "job $JOBID ended before this run finished (exit code $rc)"
                echo "$JOBID done $rc" > "$dir/.simlaunch-job"
            fi
        fi
        if [ -d "${JOBDIRS[$i]:-}" ]; then
            echo
            echo "=== output of ${LABELS[$i]} (${JOBDIRS[$i]}/output.log) ==="
            cat "${JOBDIRS[$i]}/output.log" 2>/dev/null
        fi
    done
    echo
    echo "job $JOBID ended with exit code $rc at $(date)"
}

# --- end of the helpers ------------------------------------------------------

# Called by `simlaunch submit` after the job is queued.
if [ "${1:-}" = --queued ]; then
    JOBID=$2
    for i in "${!LABELS[@]}"; do sw_queued "$i" "${3:-}"; done
    exit 0
fi

# Called by `simlaunch cancel`: the runs that have not ended are marked cancelled.
if [ "${1:-}" = --cancelled ]; then
    for i in "${!LABELS[@]}"; do sw_cancel "$i" "${2:-cancelled}"; done
    exit 0
fi

JOBID=${SLURM_JOB_ID:-${SIMLAUNCH_JOB_ID:-}}
if [ -z "$JOBID" ]; then
    echo "no job ID: submit with sbatch, or set SIMLAUNCH_JOB_ID" >&2
    exit 2
fi
SW_T0=$(date +%s)
SW_STARTED=$(sw_now)
# without Slurm, this is how the job is stopped: kill $(cat <file>)
if [ "$USE_SLURM" = 0 ]; then echo $$ > "$SCRATCH/logs/$SPEC-$JOBID.pid"; fi

# The environment. Everything is set here; nothing is taken from the
# submitting shell.
unset JULIA_LOAD_PATH JULIA_PROJECT JULIA_CPU_TARGET   # set below where the caches were compiled for a target
export JULIA_DEPOT_PATH="$DEPOT:"         # the study's depot, then Julia's own; not ~/.julia
export OPENBLAS_NUM_THREADS=1
export JULIA_PKG_PRECOMPILE_AUTO=0

echo "SimLaunch job $JOBID: study $STUDY, spec $SPEC, site $SITE, host $(hostname -s), $(date)"
lscpu 2>/dev/null | grep -m1 'Model name' || sysctl -n machdep.cpu.brand_string 2>/dev/null || true
nvidia-smi --query-gpu=name,memory.total --format=csv,noheader || true

trap finish EXIT
trap on_term TERM INT

# Every run gets a new directory of its own for this job.
for i in "${!LABELS[@]}"; do
    if [ "${SKIP[$i]:-0}" = 1 ]; then continue; fi
    JOBDIRS[$i]=$(new_job_dir "$i")
    mkdir -p "${JOBDIRS[$i]}" || exit 1
done

# The environment must be precompiled for this Julia and these flags:
# a job compiles nothing.
"$JULIA" --startup-file=no --project="$CODE"/envs/default-cuda "$TOOLS"/check_precompiled.jl || exit 3

# The runs. Each starts in its own job directory, with its output in output.log.
run_0() {   # n3
    exec "$JULIA" -t 8 --project="$CODE"/envs/default-cuda "$PROJECT"/examples/hello.jl n=3
}

# One run after another.
rc=0
for i in "${!LABELS[@]}"; do
    if [ "${SKIP[$i]:-0}" = 1 ]; then continue; fi
    if [ -n "$TERMINATED" ]; then rc=143; break; fi
    ( run_one "$i" ) &
    PIDS=($!)
    wait_runs || rc=1
done
exit $rc
